style.css:
@-moz-document domain("janitorai.com") {
/* ===== MAIN BACKGROUND & TEXT COLORS ===== */
    body {
        background-color: #1e1e1e !important;
        color: #e8e8e8 !important;
        font-family: 'Segoe UI', 'Inter', 'SF Pro Text', -apple-system, BlinkMacSystemFont, 'Roboto', sans-serif !important;
        line-height: 1.6 !important;
    }
    
    /* ===== IMPROVE READABILITY FOR CHAT CONTAINER ===== */
    .chat-container, .message-container, .conversation-area {
        background-color: #2a2a2a !important;
        border: 1px solid #404040 !important;
        border-radius: 8px !important;
    }
    
    /* ===== BETTER FONT STYLING FOR ALL TEXT ===== */
    * {
        text-shadow: 0 0 0.5px rgba(255, 255, 255, 0.1) !important;
        font-weight: 400 !important;
    }
    
    /* ===== NARRATIVE TEXT (text with asterisks *like this*) ===== */
    .message-content em, 
    .message-content i,
    [class*="message"] em,
    [class*="message"] i,
    .chat-message em,
    .chat-message i {
        color: #a8d8ff !important;        /* Soft blue for narrative/actions */
        font-style: italic !important;
        font-weight: 500 !important;
        background-color: rgba(168, 216, 255, 0.08) !important;
        padding: 2px 4px !important;
        border-radius: 3px !important;
        border-left: 2px solid #a8d8ff !important;
    }
    
    /* ===== REGULAR DIALOGUE TEXT ===== */
    .message-content, 
    [class*="message-content"],
    .chat-message,
    [class*="text"]:not(em):not(i) {
        color: #f0f0f0 !important;        /* Clean white for dialogue */
        font-size: 15px !important;
        letter-spacing: 0.02em !important;
    }
    
    /* ===== HEADERS & TITLES ===== */
    h1, h2, h3, h4, h5, h6,
    [class*="title"],
    [class*="header"] {
        color: #ffffff !important;
        font-weight: 600 !important;
        border-bottom: 1px solid #404040 !important;
        padding-bottom: 8px !important;
    }
    
    /* ===== INPUT AREA STYLING ===== */
    textarea, 
    input[type="text"],
    .message-input,
    [class*="input"] {
        background-color: #2a2a2a !important;
        color: #e8e8e8 !important;
        border: 1px solid #404040 !important;
        border-radius: 6px !important;
        font-family: inherit !important;
        font-size: 14px !important;
        padding: 12px !important;
    }
    
    textarea:focus,
    input[type="text"]:focus {
        border-color: #a8d8ff !important;
        box-shadow: 0 0 0 2px rgba(168, 216, 255, 0.2) !important;
        outline: none !important;
    }
    
    /* ===== BUTTONS ===== */
    button,
    [class*="button"] {
        background-color: #3a3a3a !important;
        color: #ffffff !important;
        border: 1px solid #505050 !important;
        border-radius: 6px !important;
        transition: all 0.2s ease !important;
    }
    
    button:hover,
    [class*="button"]:hover {
        background-color: #4a4a4a !important;
        border-color: #a8d8ff !important;
    }
    
    /* ===== SCROLLBAR STYLING ===== */
    ::-webkit-scrollbar {
        width: 8px !important;
    }
    
    ::-webkit-scrollbar-track {
        background: #2a2a2a !important;
    }
    
    ::-webkit-scrollbar-thumb {
        background: #404040 !important;
        border-radius: 4px !important;
    }
    
    ::-webkit-scrollbar-thumb:hover {
        background: #505050 !important;
    }
    
    /* ===== MESSAGE BUBBLES OR CARDS ===== */
    .message-bubble,
    [class*="bubble"],
    [class*="card"] {
        background-color: #2a2a2a !important;
        border: 1px solid #404040 !important;
        border-radius: 8px !important;
        margin: 8px 0 !important;
        padding: 12px 16px !important;
    }
    
    /* ===== REDUCE EYE STRAIN WITH SOFT SHADOWS ===== */
    .container, .main-content, .sidebar {
        box-shadow: none !important;
        background-image: none !important;
    }
    
    /* ===== LINKS ===== */
    a {
        color: #a8d8ff !important;
        text-decoration: none !important;
    }
    
    a:hover {
        color: #c0e4ff !important;
        text-decoration: underline !important;
    }
    
    /* ===== SELECTION COLOR ===== */
    ::selection {
        background-color: rgba(168, 216, 255, 0.3) !important;
        color: #ffffff !important;
    }
}
